1: ---
2: - name: Merge and transform image mirrors to registries.conf format
3:   vars:
4:     combined_mirrors: |-
5:       {%- set c = dict() %}
6:       {%- for mirror in utils_image_mirrors %}
7:       {%- set s = mirror.source %}
8:       {%- set m = mirror.mirrors %}
9:       {%- if c.get(s) %}
10:       {%- set _ = c.update({s: (c[s] + m) | unique | list}) %}
11:       {%- else %}
12:       {%- set _ = c.update({s: m | list}) %}
13:       {%- endif %}
14:       {%- endfor %}

